  "wellness.is46TooEarly": "Is 46 too early?",
  "wellness.noInIndiaTheUsualAge": "No. In India the usual age is about 46 or 47 — around six years earlier than in Western countries, which is why most advice you read online will not match what is happening to you.",
  "wellness.whyCanINotSleep": "Why can I not sleep?",
  "wellness.nightSweatsAndBrokenSleepAre": "Night sweats and broken sleep are the most common complaint, and the one that most affects work the next day. It passes, but it can take years, and there are things that help.",
  "wellness.whyDoIAcheEverywhere": "Why do I ache everywhere?",
  "wellness.jointAndMusclePainIsVery": "Joint and muscle pain is very common and rarely explained to women. For anyone doing physical work it is often the symptom that costs the most days.",
  "wellness.isThereAnythingThatHelps": "Is there anything that helps?",
  "wellness.yesAndAlmostNobodyInIndia": "Yes — and almost nobody in India gets it. Fewer than 1 woman in 100 takes anything for this. A doctor can talk you through what is available, and much of it is cheap.",
  "wellness.amIImaginingIt": "Am I imagining it?",
  "wellness.noInAStudyOfEmployed": "No. In a study of employed Indian women aged 45 to 65, nearly three in four had moderate or severe symptoms, and four in ten said their ability to work had dropped.",
