  "cycle.heatOnYourLowerBellyOr": "Heat on your lower belly or back — a hot water bottle or a warm towel. This has good evidence behind it.",
  "cycle.warmDrinksGingerTeaMayHelp": "Warm drinks. Ginger tea may help some women.",
  "cycle.painkillersLikeIbuprofenOrParacetamolAsk": "Painkillers like ibuprofen or paracetamol. Ask a pharmacist which suits you, especially if you have asthma or stomach problems.",
  "cycle.seeADoctorIf": "See a doctor if",
  "cycle.thePainStopsYouFromWorking": "The pain stops you from working or going out.",
  "cycle.youHavePainBetweenPeriodsOr": "You have pain between periods, or during or after sex.",
  "cycle.thePainHasBecomeMuchWorse": "The pain has become much worse than it used to be.",
  "cycle.nhsPeriodPain": "NHS — Period pain",
  "cycle.nutritionDuringYourPeriod": "Nutrition During Your Period",
  "cycle.foodsThatSupportYourBody": "Foods that support your body",
  "cycle.replaceTheIronYouLose": "Replace the iron you lose",
  "cycle.bleedingTakesIronWithItAnd": "Bleeding takes iron with it, and many women in India are already low. Iron-rich foods help you feel less tired.",
  "cycle.goodSources": "Good sources",
  "cycle.palakMethiAndOtherLeafyGreens": "Palak, methi and other leafy greens",
  "cycle.dalRajmaChanaAndSprouts": "Dal, rajma, chana and sprouts",
  "cycle.eggsFishAndMeatIfYou": "Eggs, fish and meat, if you eat them",
  "cycle.datesAndDriedFruit": "Dates and dried fruit",
  "cycle.helpItWork": "Help it work",
  "cycle.vitaminCHelpsYourBodyTake": "Vitamin C helps your body take in iron. Squeeze lemon on your dal, or eat an amla or orange with the meal. Tea and coffee get in the way — have them an hour apart from food.",
  "cycle.forBloating": "For bloating",
  "cycle.lessSaltMoreWaterBananasAnd": "Less salt, more water. Bananas and curd are gentle on the stomach.",
  "cycle.whoAnaemiaFactSheet": "WHO — Anaemia fact sheet",
  "cycle.nhsIronDeficiencyAnaemia": "NHS — Iron deficiency anaemia",
  "cycle.understandingYourHormones": "Understanding Your Hormones",
  "cycle.aSimpleGuideForEveryWoman": "A simple guide for every woman",
  "cycle.oneCycleFourPhases": "One cycle, four phases",
  "cycle.periodAboutDays15Hormones": "Period (about days 1–5): hormones are at their lowest. Energy often dips.",
  "cycle.follicularAfterYourPeriodEstrogenRises": "Follicular (after your period): estrogen rises. Many women feel lighter and more energetic.",
  "cycle.ovulationAroundDay14OfA": "Ovulation (around day 14 of a 28-day cycle): an egg is released. You may feel more confident.",
  "cycle.lutealTheLastTwoWeeksProgesterone": "Luteal (the last two weeks): progesterone rises, then both hormones fall. This is when PMS moods and cravings can come.",
  "cycle.yourCycleIsYours": "Your cycle is yours",
  "cycle.anythingFrom21To35Days": "Anything from 21 to 35 days is typical for adults, and it can change after a baby, with stress, or as you get closer to menopause. Tracking helps you learn your own pattern.",
  "cycle.talkToADoctorIf": "Talk to a doctor if",
  "cycle.yourCyclesAreOftenShorterThan": "Your cycles are often shorter than 21 days or longer than 35.",
  "cycle.yourPeriodsStopForThreeMonths": "Your periods stop for three months or more, and you are not pregnant.",
  "cycle.yourCycleSuddenlyBecomesVeryIrregular": "Your cycle suddenly becomes very irregular.",
  "cycle.acogAbnormalUterineBleeding": "ACOG — Abnormal Uterine Bleeding",
  "cycle.nhsPeriods": "NHS — Periods",
  "cycle.whenYourPeriodLastsLonger": "When your period lasts longer",
  "cycle.whatIsUsual": "What is usual",
  "cycle.mostPeriodsLastBetween2And": "Most periods last between 2 and 7 days. A period that goes on longer than 7 days is worth checking with a doctor — it is usually treatable, and it is not something to just put up with.",
  "cycle.commonReasons": "Common reasons",
  "cycle.hormoneChangesAfterABabyNear": "Hormone changes — after a baby, near menopause, or with stress",
  "cycle.pcosOrThyroidProblems": "PCOS or thyroid problems",
  "cycle.fibroidsOrPolypsInTheWomb": "Fibroids or polyps in the womb",
  "cycle.someContraceptivesLikeTheCopperIud": "Some contraceptives, like the copper IUD",
  "cycle.signsItIsHeavy": "Signs it is heavy",
  "cycle.youNeedToChangeAPad": "You need to change a pad every hour or two",
  "cycle.clotsBiggerThanATwoRupee": "Clots bigger than a two-rupee coin",
  "cycle.youFeelVeryTiredDizzyOr": "You feel very tired, dizzy or breathless",
  "cycle.aGovernmentHealthCentreCanCheck": "A government health centre can check you and test your iron for free. Bring the dates from your tracker — they help the doctor more than you might think.",
  "cycle.nhsHeavyPeriods": "NHS — Heavy periods",
  "cycle.acogHeavyMenstrualBleeding": "ACOG — Heavy Menstrual Bleeding",
  "cycle.pcosAndPcodSimplyExplained": "PCOS and PCOD, simply explained",
  "cycle.whatTheyAreAndWhatTo": "What they are, and what to do",
  "cycle.whatItIs": "What it is",
  "cycle.pcosPolycysticOvarySyndromeIsA": "PCOS (polycystic ovary syndrome) is a common hormone condition. In India it is often called PCOD, and the two names are usually used for the same thing.",
  "cycle.commonSigns": "Common signs",
  "cycle.irregularOrMissedPeriods": "Irregular or missed periods",
  "cycle.acneOrExtraHairOnThe": "Acne, or extra hair on the face or body",
  "cycle.weightGainThatIsHardTo": "Weight gain that is hard to shift",
  "cycle.difficultyGettingPregnant": "Difficulty getting pregnant",
  "cycle.howItIsFound": "How it is found",
  "cycle.aDoctorLooksAtYourPeriods": "A doctor looks at your periods and symptoms, and may order a blood test and an ultrasound. You need two of three signs — you do not need cysts on a scan to have it.",
  "cycle.thereIsNoCureButIt": "There is no cure, but it can be managed well: regular movement, balanced meals, and medicines a doctor can prescribe for periods, skin and fertility. It is not your fault.",
