  "local.iStoppedChargingByPityAnd": "I stopped charging by pity and started charging by the hour.",
  "local.forElevenYearsITookWhatever": "For eleven years I took whatever people offered. A workshop here taught me to count my own hours. The same blouse now brings three times what it did, and I have not lost a single customer.",
  "local.homeBaking": "Home baking",
  "local.malviyaNagarJaipur": "Malviya Nagar, Jaipur",
  "local.theSavingsCirclePaidForMy": "The savings circle paid for my oven. Six women I had never met.",
  "local.iCouldNotGetALoan": "I could not get a loan and would not ask my husband. Twelve of us put in ₹500 a month. When my turn came I had ₹6,000 in one go — enough for a proper oven. Now I bake forty cakes a month.",
  "local.bagruJaipur": "Bagru, Jaipur",
  "local.oneMelaDidMoreThanA": "One mela did more than a year of hoping someone would walk past.",
  "local.ourVillageIsOffTheRoad": "Our village is off the road. I took a stall at the Diwali mela with two other women and we sold everything by three o'clock. Half of those buyers still order from me.",
