const en = { ...core, ...chrome, ...screens } as const;

export type CoreKey = keyof typeof core;
export type ChromeKey = keyof typeof chrome;
export type ScreenKey = keyof typeof screens;
export type MessageKey = CoreKey | ChromeKey | ScreenKey;

/**
 * Core keys are compile-enforced in every language; chrome keys are optional
 * and fall back to English. See the note on `chrome` above.
 */
export type Catalog = Record<CoreKey, string> &
  Partial<Record<ChromeKey, string>> &
  Partial<Record<ScreenKey, string>>;

export default en;
